// asksForBlock: does some sentence of the message ask the controller for its return block, as opposed to stating
// that the block was missing ("your last reply was in prose, not the return block", "you did not, as asked, return
// the block")? Sentences split at . ; : ! ? and line breaks; clauses split at commas. A sentence asks when
//   1. an ask verb in its base form stands in imperative position: it opens the sentence (leaders such as "then"
//      and "please" may precede it), it follows a leader inside a clause that "you" or "they" does not open
//      ("finish the unit and end with ...", "..., so return the block now"), it opens a clause after a comma in a
//      sentence where no earlier clause breaks off at an auxiliary ("once the gates pass, end with ..." yes;
//      "you did not, as asked, return ..." no), or it follows a modal ("must end", "need to return", "can you end");
//   2. or a demand verb follows "I" or "we" ("I need the status block");
//   3. or the sentence says what the final message is to be ("your final message is / must be the return block");
//   and in every case the return block follows within the same clause: "return block", "status block" or a
//   determiner directly before "block" ("the block", "your block"), so "the normalisation block" and "the verdict
//   block" do not count; the span may not cross a comma or a subordinator ("since", "as", "because": "finish the
//   unit since the return block is missing" does not count); and no negation ("not", "never", "without", "failed
//   to", "instead of", "no ... block", "was") and no commentary ("why", "note", "tell") stands anywhere in that
//   clause up to "block". The bare name "return block" is not an ask either ("return block missing"): the verb
//   "return" is followed by "block" alone, which is neither a block name nor a determiner before "block".
//   Past-tense diagnoses never match: only base forms are listed, and "reply" or "answer" after "your" is not in
//   imperative position. Known false failures, read by hand: "never end a unit without the block", "do not stop
//   and send the block", an ask whose block sits after a comma ("end, as agreed, with the block"), and an ask that
//   names the block by another modifier ("end with the six-field block"; "the six-field return block" counts).
const BLOCK_ASK = {
  verbs: ['end', 'finish', 'close', 'conclude', 'wrap', 'reply', 'respond', 'answer', 'send', 'give', 'return', 'produce', 'write', 'print', 'include', 'provide', 'deliver', 'append', 'add', 'use', 'make'],
  demands: ['need', 'want', 'expect', 'require'],
  demanders: ['I', 'we'],
  leaders: ['and', 'then', 'so', 'but', 'or', 'now', 'please', 'also', 'just', 'next', 'finally'],
  subjects: ['you', 'they'],
  modals: ['must', 'should', 'shall', 'will', 'need to', 'needs to', 'have to', 'has to', 'is to', 'are to', 'ought to', 'be sure to', 'remember to', 'ensure you', 'ensure that you', 'can you', 'could you', 'would you', 'will you'],
  adverbs: ['first', 'then', 'now', 'also'],
  auxiliaries: [String.raw`\bdid`, String.raw`\bdo`, String.raw`\bdoes`, String.raw`\bnot`, String.raw`n['’]t`, String.raw`\bnever`, String.raw`\bto`],
  negations: [String.raw`\bnot\b`, String.raw`n['’]t\b`, String.raw`\bnever\b`, String.raw`\bnone\b`, String.raw`\bwithout\b`, String.raw`\bmissing\b`, String.raw`\black(?:s|ed|ing)?\b`, String.raw`\bomit(?:s|ted)?\b`, String.raw`\bfailed to\b`, String.raw`\bforgot to\b`, String.raw`\bneglected to\b`, String.raw`\binstead of\b`, String.raw`\bin place of\b`, String.raw`\brather than\b`, String.raw`\bother than\b`, String.raw`\bno need\b`, String.raw`\bno(?:\s+[\w-]+){0,2}\s+block\b`, String.raw`\bwas\b`, String.raw`\bwere\b`],
  commentary: ['why', 'whether', 'note', 'explain', 'tell', 'say', 'see'],
  subordinators: ['since', 'as', 'because', 'given', 'while', 'though', 'although', 'until', 'unless'],
  blockNames: ['return', 'status'],
  finalQualifiers: ['final', 'last', 'next', 'closing'],
  finalNouns: ['message', 'reply', 'answer', 'response', 'output'],
  copulas: ['is', 'must be', 'should be', 'will be', 'has to be', 'needs to be', 'is to be', 'shall be', 'ought to be'],
  predicateQualifiers: ['only', 'just', 'exactly', 'nothing but', 'verbatim'],
  articles: ['the', 'your', 'a', 'its'],
}
function blockAskChecker(L) {
  const alt = list => list.join('|')
  const leaders = new RegExp(String.raw`^\W*(?:(?:${alt(L.leaders)})\s+)*`, 'i')
  const subjectLed = new RegExp(String.raw`^\W*(?:${alt(L.subjects)})\b`, 'i')
  const afterLeader = new RegExp(String.raw`(?:^|\W)(?:${alt(L.leaders)})\s+$`, 'i')
  const afterModal = new RegExp(String.raw`(?:^|\W)(?:${alt(L.modals)})\s+(?:(?:${alt(L.adverbs)})\s+)?$`, 'i')
  const afterDemander = new RegExp(String.raw`(?:^|\W)(?:${alt(L.demanders)})\s+$`, 'i')
  const auxiliaryEnd = new RegExp(String.raw`(?:${alt(L.auxiliaries)})\W*$`, 'i')
  const vetoed = new RegExp(String.raw`${alt(L.negations)}|\b(?:${alt(L.commentary)})\b`, 'i')
  const verb = new RegExp(String.raw`\b(?:${alt(L.verbs)}|${alt(L.demands)})\b`, 'gi')
  // The tail must reach the return block itself, within the clause and before any subordinator.
  const blockAfter = new RegExp(String.raw`^(?:(?!\b(?:${alt(L.subordinators)})\b)[^,]){0,80}?\b(?:${alt(L.blockNames)}|${alt(L.articles)})\s+block\b`, 'i')
  // "final message is the return block": the block is the direct predicate, so no second determiner before "block".
  const finalMessageIsBlock = new RegExp(String.raw`\b(?:${alt(L.finalQualifiers)})\s+(?:${alt(L.finalNouns)})\s+(?:${alt(L.copulas)})\s+(?:(?:${alt(L.predicateQualifiers)})\s+)?(?:${alt(L.articles)})\s+(?:(?!(?:the|a|an|your|its|this|that)\b)[\w-]+\s+){0,3}block\b`, 'i')
  const asks = sentence => {
    if (finalMessageIsBlock.test(sentence)) return true
    for (const m of sentence.matchAll(verb)) {
      const prefix = sentence.slice(0, m.index)
      const parts = prefix.split(',')
      const clause = parts[parts.length - 1]
      const tail = blockAfter.exec(sentence.slice(m.index + m[0].length))
      if (!tail || vetoed.test(clause + m[0] + tail[0])) continue
      if (L.demands.includes(m[0].toLowerCase())) { if (afterDemander.test(clause)) return true; continue }
      if (afterModal.test(clause)) return true
      if (prefix.replace(leaders, '') === '') return true
      if (afterLeader.test(clause) && !subjectLed.test(clause.replace(leaders, ''))) return true
      if (parts.length > 1 && clause.trim() === '' && !parts.slice(0, -1).some(part => auxiliaryEnd.test(part))) return true
    }
    return false
  }
  return text => (text || '').split(/[.;:!?\n]+/).some(asks)
}
const asksForBlock = blockAskChecker(BLOCK_ASK)

